// SPDX-License-Identifier: GPL-3.0-only
//! Rust port of the `cat-shell-risk-commander` shell command scorer.
//!
//! The published model is a scikit-learn `TfidfVectorizer(analyzer="char_wb",
//! ngram_range=(3, 5), lowercase=True, sublinear_tf=True, norm="l2")` feeding a
//! binary logistic regression, exported as `model.json`. Decision scores match
//! scikit-learn 1.8 within floating-point rounding; the parity corpus is
//! generated by `scripts/generate_shell_command_parity_fixtures.py`.
//!
//! The scorer only sees command text. It never executes, parses or expands the
//! command, so it is one signal next to sandboxing and permission policy.

use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::path::Path;

use serde::Deserialize;

use crate::detectors::NativeDetection;
use crate::{EvaluationResult, EvidenceSpan};

/// Class name returned when the decision score is above the threshold.
pub const SHELL_RISK_CLASS: &str = "shell_risk";
const SAFE_CLASS: &str = "safe";
const MAX_EVIDENCE_SPANS: usize = 3;
const EVIDENCE_FEATURES: usize = 8;

#[derive(Deserialize)]
struct ModelFile {
    format_version: u32,
    model_type: String,
    name: String,
    vectorizer: VectorizerConfig,
    feature_dtype: String,
    idf_dtype: String,
    vocabulary: HashMap<String, u32>,
    idf: Vec<f64>,
    weights: Vec<f64>,
    intercept: f64,
    thresholds: BTreeMap<String, f64>,
    default_threshold_policy: String,
    decision_rule: String,
}

#[derive(Deserialize)]
struct VectorizerConfig {
    analyzer: String,
    ngram_range: [usize; 2],
    lowercase: bool,
    strip_accents: Option<String>,
    sublinear_tf: bool,
    norm: Option<String>,
    use_idf: bool,
}

#[derive(Deserialize)]
struct BundleManifest {
    files: HashMap<String, BundleFile>,
}

#[derive(Deserialize)]
struct BundleFile {
    sha256: String,
}

/// A loaded TF-IDF character n-gram logistic-regression model.
pub struct ShellRiskModel {
    name: String,
    vocabulary: HashMap<Box<str>, u32>,
    idf: Vec<f32>,
    weights: Vec<f64>,
    intercept: f64,
    min_n: usize,
    max_n: usize,
    thresholds: BTreeMap<String, f64>,
    default_policy: String,
}

impl ShellRiskModel {
    /// Parse and validate a `format_version: 1` `model.json` document.
    pub fn from_json_slice(bytes: &[u8]) -> Result<Self, String> {
        let file: ModelFile = serde_json::from_slice(bytes)
            .map_err(|error| format!("invalid shell risk model JSON: {error}"))?;
        if file.format_version != 1 {
            return Err(format!(
                "unsupported shell risk model format_version {}",
                file.format_version
            ));
        }
        if file.model_type != "tfidf_char_wb_logistic_regression" {
            return Err(format!(
                "unsupported shell risk model_type {}",
                file.model_type
            ));
        }
        let vectorizer = &file.vectorizer;
        let [min_n, max_n] = vectorizer.ngram_range;
        if vectorizer.analyzer != "char_wb"
            || !vectorizer.lowercase
            || vectorizer.strip_accents.is_some()
            || !vectorizer.sublinear_tf
            || vectorizer.norm.as_deref() != Some("l2")
            || !vectorizer.use_idf
            || min_n == 0
            || min_n > max_n
        {
            return Err("unsupported shell risk vectorizer configuration".to_string());
        }
        if file.feature_dtype != "float32" || file.idf_dtype != "float32" {
            return Err("shell risk model must use float32 features and idf".to_string());
        }
        if file.decision_rule != "score > threshold" {
            return Err(format!(
                "unsupported shell risk decision_rule {}",
                file.decision_rule
            ));
        }
        let features = file.vocabulary.len();
        if file.idf.len() != features || file.weights.len() != features {
            return Err(format!(
                "shell risk model has {features} vocabulary entries, {} idf values and {} weights",
                file.idf.len(),
                file.weights.len()
            ));
        }
        let mut seen = vec![false; features];
        for &index in file.vocabulary.values() {
            let slot = seen
                .get_mut(index as usize)
                .ok_or_else(|| format!("shell risk vocabulary index {index} is out of range"))?;
            if std::mem::replace(slot, true) {
                return Err(format!("shell risk vocabulary index {index} is duplicated"));
            }
        }
        if !file.thresholds.contains_key(&file.default_threshold_policy) {
            return Err(format!(
                "shell risk default threshold policy {} is not defined",
                file.default_threshold_policy
            ));
        }
        Ok(Self {
            name: file.name,
            vocabulary: file
                .vocabulary
                .into_iter()
                .map(|(term, index)| (term.into_boxed_str(), index))
                .collect(),
            idf: file.idf.into_iter().map(|value| value as f32).collect(),
            weights: file.weights,
            intercept: file.intercept,
            min_n,
            max_n,
            thresholds: file.thresholds,
            default_policy: file.default_threshold_policy,
        })
    }

    /// Load `model.json` from a downloaded bundle after checking its SHA-256
    /// against the bundle's `manifest.json`.
    pub fn from_bundle_dir(dir: &Path) -> Result<Self, String> {
        let manifest_path = dir.join("manifest.json");
        let manifest: BundleManifest = serde_json::from_slice(
            &fs::read(&manifest_path)
                .map_err(|error| format!("failed to read {}: {error}", manifest_path.display()))?,
        )
        .map_err(|error| format!("invalid {}: {error}", manifest_path.display()))?;
        let expected = manifest
            .files
            .get("model.json")
            .ok_or_else(|| format!("{} does not list model.json", manifest_path.display()))?;
        let model_path = dir.join("model.json");
        let bytes = fs::read(&model_path)
            .map_err(|error| format!("failed to read {}: {error}", model_path.display()))?;
        let actual = sha256_hex(&bytes);
        if !actual.eq_ignore_ascii_case(&expected.sha256) {
            return Err(format!(
                "{} sha256 {actual} does not match manifest {}",
                model_path.display(),
                expected.sha256
            ));
        }
        Self::from_json_slice(&bytes)
    }

    /// Model name recorded in `model.json`.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Threshold policy used when none is selected explicitly.
    pub fn default_threshold_policy(&self) -> &str {
        &self.default_policy
    }

    /// Decision threshold for a named policy.
    pub fn threshold(&self, policy: &str) -> Option<f64> {
        self.thresholds.get(policy).copied()
    }

    /// Raw logistic-regression decision score (an uncalibrated logit).
    pub fn decision_score(&self, text: &str) -> f64 {
        self.tfidf(text)
            .into_iter()
            .fold(self.intercept, |score, (index, value)| {
                score + self.weights[index as usize] * f64::from(value)
            })
    }

    /// L2-normalized TF-IDF features sorted by vocabulary index.
    fn tfidf(&self, text: &str) -> Vec<(u32, f32)> {
        let mut counts = HashMap::<u32, u32>::new();
        self.visit_ngrams(text, |ngram, _| {
            if let Some(&index) = self.vocabulary.get(ngram) {
                *counts.entry(index).or_default() += 1;
            }
        });
        let mut values = counts
            .into_iter()
            .map(|(index, tf)| (index, ((tf as f32).ln() + 1.0) * self.idf[index as usize]))
            .collect::<Vec<_>>();
        values.sort_unstable_by_key(|(index, _)| *index);
        // scikit-learn accumulates the row norm in double precision and stores
        // the normalized values back into the float32 matrix.
        let squared = values
            .iter()
            .map(|(_, value)| f64::from(value * value))
            .sum::<f64>();
        if squared > 0.0 {
            let norm = squared.sqrt();
            for (_, value) in &mut values {
                *value = (f64::from(*value) / norm) as f32;
            }
        }
        values
    }

    /// Visit every `char_wb` n-gram of `text` with the byte range of the
    /// source characters it covers.
    fn visit_ngrams(&self, text: &str, mut visit: impl FnMut(&str, std::ops::Range<usize>)) {
        let mut padded = String::new();
        let mut bounds = Vec::new();
        for_each_word(text, |word_start, word| {
            let lowered = word.to_lowercase();
            padded.clear();
            padded.push(' ');
            padded.push_str(&lowered);
            padded.push(' ');
            bounds.clear();
            bounds.extend(padded.char_indices().map(|(index, _)| index));
            bounds.push(padded.len());
            let padded_len = bounds.len() - 1;
            let source = SourceMap::new(word_start, word, padded_len - 2);
            for n in self.min_n..=self.max_n {
                let mut offset = 0;
                visit(
                    &padded[bounds[0]..bounds[n.min(padded_len)]],
                    source.range(0, n),
                );
                while offset + n < padded_len {
                    offset += 1;
                    visit(
                        &padded[bounds[offset]..bounds[offset + n]],
                        source.range(offset, n),
                    );
                }
                // Python counts a word shorter than `n` only once.
                if offset == 0 {
                    break;
                }
            }
        });
    }

    /// Evidence spans for the n-grams that push `text` towards the risk class.
    ///
    /// `source` must have the same byte layout as `text`; spans are reported
    /// against `source`.
    fn evidence(&self, text: &str, source: &str) -> Vec<EvidenceSpan> {
        let mut contributions = self
            .tfidf(text)
            .into_iter()
            .map(|(index, value)| (index, self.weights[index as usize] * f64::from(value)))
            .filter(|(_, contribution)| *contribution > 0.0)
            .collect::<Vec<_>>();
        let total = contributions.iter().map(|(_, value)| value).sum::<f64>();
        if total <= 0.0 {
            return Vec::new();
        }
        contributions.sort_unstable_by(|left, right| right.1.total_cmp(&left.1));
        contributions.truncate(EVIDENCE_FEATURES);
        let selected = contributions.into_iter().collect::<HashMap<_, _>>();

        let mut occurrences = Vec::<(u32, std::ops::Range<usize>)>::new();
        self.visit_ngrams(text, |ngram, range| {
            if let Some(&index) = self.vocabulary.get(ngram) {
                if selected.contains_key(&index) && !range.is_empty() {
                    occurrences.push((index, range));
                }
            }
        });
        let mut counts = HashMap::<u32, usize>::new();
        for (index, _) in &occurrences {
            *counts.entry(*index).or_default() += 1;
        }
        occurrences.sort_unstable_by_key(|(_, range)| (range.start, range.end));

        let mut regions = Vec::<(std::ops::Range<usize>, f64)>::new();
        for (index, range) in occurrences {
            let share = selected[&index] / counts[&index] as f64;
            match regions.last_mut() {
                Some((region, score)) if range.start <= region.end => {
                    region.end = region.end.max(range.end);
                    *score += share;
                }
                _ => regions.push((range, share)),
            }
        }
        regions.sort_unstable_by(|left, right| right.1.total_cmp(&left.1));
        regions.truncate(MAX_EVIDENCE_SPANS);
        regions.sort_unstable_by_key(|(range, _)| range.start);
        regions
            .into_iter()
            .map(|(range, score)| EvidenceSpan {
                label: SHELL_RISK_CLASS.to_string(),
                text: source[range.clone()].to_string(),
                score: (score / total).clamp(0.0, 1.0),
                start_byte: range.start,
                end_byte: range.end,
                start_char: source[..range.start].chars().count(),
                end_char: source[..range.end].chars().count(),
            })
            .collect()
    }
}

/// Maps padded n-gram character offsets back to the source word.
struct SourceMap {
    /// Byte offset of every source character plus the word end, when
    /// lowercasing kept the character count; otherwise only the word bounds.
    bounds: Vec<usize>,
    exact: bool,
}

impl SourceMap {
    fn new(word_start: usize, word: &str, lowered_chars: usize) -> Self {
        let mut bounds = word
            .char_indices()
            .map(|(index, _)| word_start + index)
            .collect::<Vec<_>>();
        bounds.push(word_start + word.len());
        let exact = bounds.len() - 1 == lowered_chars;
        if !exact {
            bounds = vec![word_start, word_start + word.len()];
        }
        Self { bounds, exact }
    }

    /// Source range for the padded characters `offset..offset + n`.
    fn range(&self, offset: usize, n: usize) -> std::ops::Range<usize> {
        let chars = self.bounds.len() - 1;
        if !self.exact {
            return self.bounds[0]..self.bounds[chars];
        }
        // Padded index 0 and `chars + 1` are the synthetic spaces.
        let start = offset.max(1) - 1;
        let end = (offset + n).min(chars + 1).saturating_sub(1).max(start);
        self.bounds[start.min(chars)]..self.bounds[end.min(chars)]
    }
}

/// Python `str.isspace`, which also treats the ASCII separators
/// U+001C..U+001F as whitespace.
fn is_python_whitespace(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Split like Python `str.split()` and report each word's byte offset.
fn for_each_word(text: &str, mut visit: impl FnMut(usize, &str)) {
    let mut start = None;
    for (index, c) in text.char_indices() {
        if is_python_whitespace(c) {
            if let Some(word_start) = start.take() {
                visit(word_start, &text[word_start..index]);
            }
        } else if start.is_none() {
            start = Some(index);
        }
    }
    if let Some(word_start) = start {
        visit(word_start, &text[word_start..]);
    }
}

/// Blank POSIX/PowerShell `#` comments, PowerShell `<# #>` blocks and CMD
/// `REM`/`::` lines with spaces, keeping byte offsets and line breaks.
///
/// Comment padding dilutes the character n-gram vector and is the model's
/// documented recall weakness. Returns `None` when nothing was removed.
fn strip_comments(text: &str) -> Option<String> {
    let bytes = text.as_bytes();
    let mut out = bytes.to_vec();
    let mut changed = false;
    let mut quote = None::<u8>;
    let mut line_start = true;
    let mut index = 0;
    let blank = |out: &mut Vec<u8>, range: std::ops::Range<usize>| {
        for byte in &mut out[range] {
            if *byte != b'\n' && *byte != b'\r' {
                *byte = b' ';
            }
        }
    };
    let line_end = |from: usize| {
        bytes[from..]
            .iter()
            .position(|byte| *byte == b'\n')
            .map_or(bytes.len(), |offset| from + offset)
    };
    while index < bytes.len() {
        let byte = bytes[index];
        if let Some(open) = quote {
            if byte == b'\\' && open == b'"' {
                index += 2;
                continue;
            }
            if byte == open {
                quote = None;
            }
            index += 1;
            continue;
        }
        match byte {
            b'\n' => {
                line_start = true;
                index += 1;
                continue;
            }
            b'\'' | b'"' => {
                quote = Some(byte);
                line_start = false;
                index += 1;
                continue;
            }
            b'\\' => {
                line_start = false;
                index += 2;
                continue;
            }
            b'<' if bytes.get(index + 1) == Some(&b'#') => {
                let end = text[index + 2..]
                    .find("#>")
                    .map_or(bytes.len(), |offset| index + 2 + offset + 2);
                blank(&mut out, index..end);
                changed = true;
                index = end;
                continue;
            }
            b'#' if index == 0 || is_comment_boundary(bytes[index - 1]) => {
                let end = line_end(index);
                blank(&mut out, index..end);
                changed = true;
                index = end;
                continue;
            }
            _ => {}
        }
        if line_start && !byte.is_ascii_whitespace() {
            let rest = &bytes[index..];
            let rem = rest.len() >= 3
                && rest[..3].eq_ignore_ascii_case(b"rem")
                && rest.get(3).is_none_or(|next| next.is_ascii_whitespace());
            if rem || rest.starts_with(b"::") {
                let end = line_end(index);
                blank(&mut out, index..end);
                changed = true;
                index = end;
                continue;
            }
            line_start = false;
        }
        index += 1;
    }
    if !changed {
        return None;
    }
    String::from_utf8(out).ok()
}

fn is_comment_boundary(previous: u8) -> bool {
    previous.is_ascii_whitespace() || matches!(previous, b';' | b'&' | b'|' | b'(' | b')')
}

fn sha256_hex(bytes: &[u8]) -> String {
    ring::digest::digest(&ring::digest::SHA256, bytes)
        .as_ref()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn sigmoid(value: f64) -> f64 {
    1.0 / (1.0 + (-value).exp())
}

/// Score of one command, including the comment-stripped variant.
#[derive(Debug, Clone, PartialEq)]
pub struct ShellRiskScore {
    /// Maximum decision score over the scored variants.
    pub decision_score: f64,
    /// Decision score of the unmodified text.
    pub full_score: f64,
    /// Decision score after comments were blanked, when any were found.
    pub comments_stripped_score: Option<f64>,
    /// Variant that produced `decision_score`: `full` or `comments_stripped`.
    pub variant: &'static str,
    /// Threshold of the selected policy.
    pub threshold: f64,
    /// Whether `decision_score > threshold`.
    pub flagged: bool,
}

/// Shell command scanner for the `shell_command` category.
pub struct ShellRiskPipeline {
    model: ShellRiskModel,
    policy: String,
    threshold: f64,
}

impl ShellRiskPipeline {
    /// Use the model's default threshold policy.
    pub fn new(model: ShellRiskModel) -> Self {
        let policy = model.default_threshold_policy().to_string();
        let threshold = model.threshold(&policy).expect("validated default policy");
        Self {
            model,
            policy,
            threshold,
        }
    }

    /// Use a named threshold policy from `model.json`.
    pub fn with_threshold_policy(model: ShellRiskModel, policy: &str) -> Result<Self, String> {
        let threshold = model
            .threshold(policy)
            .ok_or_else(|| format!("unknown shell risk threshold policy {policy}"))?;
        Ok(Self {
            model,
            policy: policy.to_string(),
            threshold,
        })
    }

    /// Load a verified bundle with the default threshold policy.
    pub fn from_bundle_dir(dir: &Path) -> Result<Self, String> {
        ShellRiskModel::from_bundle_dir(dir).map(Self::new)
    }

    /// Loaded model.
    pub fn model(&self) -> &ShellRiskModel {
        &self.model
    }

    /// Selected threshold policy.
    pub fn threshold_policy(&self) -> &str {
        &self.policy
    }

    /// Score the text and its comment-stripped variant.
    pub fn score(&self, text: &str) -> ShellRiskScore {
        self.score_with_variant(text).0
    }

    fn score_with_variant(&self, text: &str) -> (ShellRiskScore, Option<String>) {
        let full_score = self.model.decision_score(text);
        let stripped = strip_comments(text);
        let comments_stripped_score = stripped
            .as_deref()
            .map(|stripped| self.model.decision_score(stripped));
        let (decision_score, variant) = match comments_stripped_score {
            Some(score) if score > full_score => (score, "comments_stripped"),
            _ => (full_score, "full"),
        };
        (
            ShellRiskScore {
                decision_score,
                full_score,
                comments_stripped_score,
                variant,
                threshold: self.threshold,
                flagged: decision_score > self.threshold,
            },
            stripped,
        )
    }

    pub(crate) fn detect(&self, text: &str) -> NativeDetection {
        let (score, stripped) = self.score_with_variant(text);
        let scored_text = match score.variant {
            "comments_stripped" => stripped.as_deref().unwrap_or(text),
            _ => text,
        };
        let evidence_spans = if score.flagged {
            self.model.evidence(scored_text, text)
        } else {
            Vec::new()
        };
        let mut details = HashMap::from([
            ("model".to_string(), serde_json::json!(self.model.name())),
            (
                "decision_score".to_string(),
                serde_json::json!(score.decision_score),
            ),
            ("threshold".to_string(), serde_json::json!(score.threshold)),
            (
                "threshold_policy".to_string(),
                serde_json::json!(self.policy),
            ),
            ("variant".to_string(), serde_json::json!(score.variant)),
            (
                "full_score".to_string(),
                serde_json::json!(score.full_score),
            ),
        ]);
        if let Some(stripped_score) = score.comments_stripped_score {
            details.insert(
                "comments_stripped_score".to_string(),
                serde_json::json!(stripped_score),
            );
        }
        NativeDetection {
            result: EvaluationResult {
                class_name: if score.flagged {
                    SHELL_RISK_CLASS
                } else {
                    SAFE_CLASS
                }
                .to_string(),
                // Distance from the threshold, squashed to 0.5..1. The model's
                // logit is not a calibrated probability.
                confidence: sigmoid((score.decision_score - score.threshold).abs()),
                level: "L1".to_string(),
            },
            evidence_spans,
            details,
        }
    }

    /// Evaluate one command.
    pub fn evaluate(&self, text: &str) -> EvaluationResult {
        self.detect(text).result
    }

    /// Evaluate commands in parallel.
    pub fn evaluate_batch(&self, texts: &[String]) -> Vec<EvaluationResult> {
        use rayon::prelude::*;
        texts.par_iter().map(|text| self.evaluate(text)).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tiny_model() -> ShellRiskModel {
        let model = serde_json::json!({
            "format_version": 1,
            "model_type": "tfidf_char_wb_logistic_regression",
            "name": "tiny",
            "vectorizer": {
                "analyzer": "char_wb", "ngram_range": [3, 5], "lowercase": true,
                "strip_accents": null, "sublinear_tf": true, "norm": "l2",
                "use_idf": true, "smooth_idf": true
            },
            "feature_dtype": "float32",
            "idf_dtype": "float32",
            "vocabulary": {" rm": 0, "rm ": 1, " rm ": 2, "-rf": 3, " ls ": 4, " ab ": 5},
            "idf": [1.0, 1.0, 1.0, 2.0, 1.0, 1.0],
            "weights": [1.0, 1.0, 1.0, 2.0, -3.0, 0.5],
            "intercept": -1.0,
            "thresholds": {"default": 0.0},
            "default_threshold_policy": "default",
            "decision_rule": "score > threshold"
        });
        ShellRiskModel::from_json_slice(model.to_string().as_bytes()).unwrap()
    }

    fn ngrams(model: &ShellRiskModel, text: &str) -> Vec<(String, String)> {
        let mut out = Vec::new();
        model.visit_ngrams(text, |ngram, range| {
            out.push((ngram.to_string(), text[range].to_string()))
        });
        out
    }

    #[test]
    fn char_wb_counts_short_words_once() {
        let grams = ngrams(&tiny_model(), "ab")
            .into_iter()
            .map(|(gram, _)| gram)
            .collect::<Vec<_>>();
        assert_eq!(grams, [" ab", "ab ", " ab "]);
    }

    #[test]
    fn char_wb_lowercases_and_maps_source_ranges() {
        let grams = ngrams(&tiny_model(), "RM -RF");
        assert_eq!(grams[0], (" rm".to_string(), "RM".to_string()));
        assert_eq!(grams[1], ("rm ".to_string(), "RM".to_string()));
        assert_eq!(grams[2], (" rm ".to_string(), "RM".to_string()));
        assert!(grams.contains(&("-rf".to_string(), "-RF".to_string())));
    }

    #[test]
    fn python_whitespace_includes_ascii_separators() {
        let model = tiny_model();
        assert_eq!(
            model.decision_score("rm\u{1c}-rf"),
            model.decision_score("rm -rf")
        );
        assert_eq!(
            model.decision_score("rm\u{a0}\u{2003}-rf"),
            model.decision_score("rm\t-rf")
        );
    }

    #[test]
    fn empty_text_scores_the_intercept() {
        assert_eq!(tiny_model().decision_score(""), -1.0);
        assert_eq!(tiny_model().decision_score(" \n\t"), -1.0);
    }

    #[test]
    fn sublinear_tf_idf_is_l2_normalized() {
        // " ls " occurs twice: tf = 1 + ln 2; it is the only vocabulary term.
        let score = tiny_model().decision_score("ls ls");
        assert!((score - (-1.0 - 3.0)).abs() < 1e-6, "{score}");
    }

    #[test]
    fn rejects_inconsistent_models() {
        let mut model: serde_json::Value = serde_json::json!({
            "format_version": 1,
            "model_type": "tfidf_char_wb_logistic_regression",
            "name": "bad",
            "vectorizer": {
                "analyzer": "char", "ngram_range": [3, 5], "lowercase": true,
                "strip_accents": null, "sublinear_tf": true, "norm": "l2", "use_idf": true
            },
            "feature_dtype": "float32", "idf_dtype": "float32",
            "vocabulary": {"abc": 0}, "idf": [1.0], "weights": [1.0], "intercept": 0.0,
            "thresholds": {"default": 0.0}, "default_threshold_policy": "default",
            "decision_rule": "score > threshold"
        });
        assert!(ShellRiskModel::from_json_slice(model.to_string().as_bytes()).is_err());
        model["vectorizer"]["analyzer"] = "char_wb".into();
        model["vocabulary"] = serde_json::json!({"abc": 1});
        assert!(ShellRiskModel::from_json_slice(model.to_string().as_bytes()).is_err());
        model["vocabulary"] = serde_json::json!({"abc": 0});
        model["default_threshold_policy"] = "missing".into();
        assert!(ShellRiskModel::from_json_slice(model.to_string().as_bytes()).is_err());
    }

    #[test]
    fn strip_comments_keeps_offsets_and_quoted_hashes() {
        let text = "rm -rf / # padding\necho \"#keep\" ${#a[@]} $# 'x # y'";
        let stripped = strip_comments(text).unwrap();
        assert_eq!(stripped.len(), text.len());
        assert_eq!(
            stripped,
            "rm -rf /          \necho \"#keep\" ${#a[@]} $# 'x # y'"
        );
        assert_eq!(strip_comments("echo \"#keep\" $#"), None);
    }

    #[test]
    fn strip_comments_handles_powershell_and_cmd() {
        assert_eq!(
            strip_comments("<# a\nb #>Remove-Item x").unwrap(),
            "    \n    Remove-Item x"
        );
        assert_eq!(
            strip_comments("REM note\r\n:: note\r\ndel x").unwrap(),
            "        \r\n       \r\ndel x"
        );
        assert_eq!(strip_comments("remove x"), None);
    }

    #[test]
    fn comment_padding_does_not_hide_a_risky_command() {
        let pipeline = ShellRiskPipeline::new(tiny_model());
        let padded = format!("rm -rf # {}", "ls ".repeat(200));
        let score = pipeline.score(&padded);
        assert_eq!(score.variant, "comments_stripped");
        assert!(score.flagged);
        assert!(score.full_score < score.decision_score);
    }

    #[test]
    fn flagged_detection_reports_evidence_against_the_source_text() {
        let pipeline = ShellRiskPipeline::new(tiny_model());
        let text = "RM -RF # ls ls ls";
        let detection = pipeline.detect(text);
        assert_eq!(detection.result.class_name, SHELL_RISK_CLASS);
        assert!(detection.result.confidence > 0.5);
        assert_eq!(detection.details["variant"], "comments_stripped");
        let spans = detection
            .evidence_spans
            .iter()
            .map(|span| (span.text.as_str(), span.start_byte, span.end_byte))
            .collect::<Vec<_>>();
        assert_eq!(spans, [("RM", 0, 2), ("-RF", 3, 6)]);

        let safe = pipeline.detect("ls");
        assert_eq!(safe.result.class_name, SAFE_CLASS);
        assert!(safe.evidence_spans.is_empty());
    }
}
